// hooks.ts against the Python originals (captions.words_for_clip + find_hook):
// fixtures/hooks.json was generated by running them on these inputs.

import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { findHook, ruleHook, sanitizeWords, sentences, wordsForClip, type Word } from "../src/hooks";

const fx = JSON.parse(readFileSync(join(import.meta.dir, "fixtures", "hooks.json"), "utf-8")) as {
  cases: Array<{ name: string; segments: never[]; clipStart: number; clipEnd: number; words: Word[]; hook: [number, number] | null }>;
};

const close = (a: Word[], b: Word[]) => {
  expect(a.map((w) => w.text)).toEqual(b.map((w) => w.text));
  a.forEach((w, i) => {
    expect(w.start).toBeCloseTo(b[i]!.start, 9);
    expect(w.end).toBeCloseTo(b[i]!.end, 9);
  });
};

describe("hooks (golden: captions.py)", () => {
  test("fixture covers hooks found and not found", () => {
    expect(fx.cases.length).toBeGreaterThanOrEqual(10);
    expect(fx.cases.some((c) => c.hook === null)).toBeTrue();
  });

  for (const c of fx.cases) {
    test(c.name, () => {
      const words = wordsForClip(c.segments, c.clipStart, c.clipEnd);
      close(words, c.words);
      const hook = findHook(words);
      if (c.hook === null) expect(hook).toBeNull();
      else {
        // Python pads its hook (-0.1 s / +0.15 s); seg_hook() pads the range the backend sends the same way.
        expect(Math.round(Math.max(0, hook![0] - 0.1) * 1000) / 1000).toBeCloseTo(c.hook[0], 6);
        expect(Math.round(Math.min(c.clipEnd - c.clipStart, hook![1] + 0.15) * 1000) / 1000).toBeCloseTo(c.hook[1], 6);
      }
    });
  }

  test("ruleHook returns absolute seconds, or null", () => {
    const c = fx.cases.find((x) => x.name === "words-offset-window")!;
    const h = ruleHook(c.segments, c.clipStart, c.clipEnd)!;
    expect(h.hookStart).toBeGreaterThan(c.clipStart);
    expect(h.hookEnd).toBeLessThanOrEqual(c.clipEnd);
    expect(ruleHook([], 0, 10)).toBeNull();
  });

  test("sanitize folds punctuation and reduplication, drops empties, keeps timings monotonic", () => {
    expect(sanitizeWords([{ text: ",", start: 0, end: 0.1 }, { text: "a", start: 1, end: 1 }, { text: " ", start: 2, end: 3 },
      { text: "b", start: 0.5, end: 0.6 }])).toEqual([{ text: "a", start: 1, end: 1.05 }, { text: "b", start: 1, end: 1.05 }]);
    expect(sentences([])).toEqual([]);
    expect(wordsForClip([{ start: 0, end: 2, words: [{ word: "pakai", start: 0.2, end: 0.6 }] }], 0, 2)).toEqual([
      { text: "pakai", start: 0.2, end: 0.6 }]);
    expect(wordsForClip([{ start: 0, end: 2, text: "  " }, {}], 0, 2)).toEqual([]);
  });
});
